 s3_4: {"no":"3-2","title":"반응속도 테스트","goal":"배경 색이 바뀌는 순간 클릭해서 걸린 시간을 재요.","files":[{"name":"기본","sprites":[{"obj":"반응속도","say":"성공 신호를 받으면 타이머 값을 말해요.","code":["ev^{성공} 신호를 받았을 때","lk:⟦op|⟦sen|타이머⟧ 와(과) [초!] 결합하기⟧ 을(를) [2] 초 동안 말하기","ctl:멈추기 {모두}","ev^{다시하기} 신호를 받았을 때","lk:[색이 바뀌면 클릭하세요!] 을(를) [0.5] 초 동안 말하기","ev:{처음부터} 신호 보내기"]},{"obj":"리셋버튼","say":"클릭하면 처음부터 신호를 보내요.","code":["ev^🚩 클릭했을 때","mo:x: [169] y: [-142] (으)로 이동하기","lk:{맨 앞쪽} 으로 순서 바꾸기","ev^이 스프라이트를 클릭했을 때","ev:{처음부터} 신호 보내기"]},{"obj":"무대","say":"조금 기다렸다가 배경을 바꾸고 타이머를 초기화해요. 무대를 클릭하면 성공 신호를 보내요.","code":["ev^🚩 클릭했을 때","lk:배경을 {배경1} (으)로 바꾸기","ctl:⟦op|[2.1] 부터 [4.2] 사이의 난수⟧ 초 기다리기","lk:다음 배경으로 바꾸기","sen:타이머 초기화","ev^{처음부터} 신호를 받았을 때","lk:배경을 {배경1} (으)로 바꾸기","ctl:⟦op|[2.1] 부터 [4.2] 사이의 난수⟧ 초 기다리기","lk:다음 배경으로 바꾸기","sen:타이머 초기화","ev^무대를 클릭했을 때","ev:{성공} 신호 보내기"]}]},{"name":"보너스 미션","sprites":[{"obj":"반응속도","say":"성공 신호를 받으면 타이머 값을 말해요.","code":["ev^{다시하기} 신호를 받았을 때","lk:[색이 바뀌면 클릭하세요!] 을(를) [0.5] 초 동안 말하기","ev:{처음부터} 신호 보내기","ev^{성공} 신호를 받았을 때","lk:⟦op|⟦sen|타이머⟧ 와(과) [초!] 결합하기⟧ 을(를) [2] 초 동안 말하기","ctl:멈추기 {모두}"]},{"obj":"리셋버튼","say":"클릭하면 처음부터 신호를 보내요.","code":["ev^🚩 클릭했을 때","mo:x: [169] y: [-142] (으)로 이동하기","lk:{맨 앞쪽} 으로 순서 바꾸기","ev^이 스프라이트를 클릭했을 때","ev:{처음부터} 신호 보내기"]},{"obj":"무대","say":"색이 바뀌기 전에 클릭하면 다시하기 신호를 보내요.","code":["ev^🚩 클릭했을 때","va:{체크} 을(를) [0] 로 정하기","lk:배경을 {배경1} (으)로 바꾸기","ctl:⟦op|[2.1] 부터 [4.2] 사이의 난수⟧ 초 기다리기","lk:다음 배경으로 바꾸기","va:{체크} 을(를) [1] 로 정하기","sen:타이머 초기화","ev^{처음부터} 신호를 받았을 때","va:{체크} 을(를) [0] 로 정하기","lk:배경을 {배경1} (으)로 바꾸기","ctl:⟦op|[2.1] 부터 [4.2] 사이의 난수⟧ 초 기다리기","va:{체크} 을(를) [1] 로 정하기","lk:다음 배경으로 바꾸기","sen:타이머 초기화","ev^무대를 클릭했을 때",["ctl:만약 ⟪op|⟦va|체크⟧ = [0]⟫ (이)라면",["ev:{다시하기} 신호 보내기"],"아니면",["ev:{성공} 신호 보내기"]]]}]}]},
 s3_5: {"no":"3-2","title":"밤이 되면 나타나는 그리핀","goal":"<b>타이머</b>로 낮과 밤이 바뀌고, 밤에만 그리핀이 나타나요.","files":[{"name":"기본","sprites":[{"obj":"Griffin","say":"배경 이름이 낮이면 숨고, 밤이면 나타나 날아다녀요.","code":["ev^🚩 클릭했을 때",["ctl:무한 반복하기",["lk:다음 모양으로 바꾸기","ctl:[0.2] 초 기다리기"]],"ev^🚩 클릭했을 때",["ctl:무한 반복하기",[["ctl:만약 ⟪op|⟦sen|{무대} 의 {배경 이름}⟧ = [낮]⟫ (이)라면",["lk:숨기기"]],["ctl:만약 ⟪op|⟦sen|{무대} 의 {배경 이름}⟧ = [밤]⟫ (이)라면",["lk:보이기"]]]],"ev^🚩 클릭했을 때","mo:회전 방식을 {왼쪽-오른쪽} (으)로 정하기",["ctl:무한 반복하기",["mo:[10] 만큼 움직이기","mo:벽에 닿으면 튕기기"]]]},{"obj":"무대","say":"타이머가 5초를 넘으면 밤, 10초를 넘으면 다시 처음으로 돌아가요.","code":["ev^🚩 클릭했을 때","sen:타이머 초기화","lk:배경을 {낮} (으)로 바꾸기",["ctl:무한 반복하기",[["ctl:만약 ⟪op|⟦sen|타이머⟧ ＞ [5]⟫ (이)라면",["lk:배경을 {밤} (으)로 바꾸기"]],["ctl:만약 ⟪op|⟦sen|타이머⟧ ＞ [10]⟫ (이)라면",["lk:배경을 {낮} (으)로 바꾸기","sen:타이머 초기화"]]]]]}]}]},
