 s4_8: {"no":"4-3","title":"자판기 만들기","goal":"번호를 입력하면 그 악기가 나와 소리를 내는 자판기를 만들어요.","files":[{"name":"기본","sprites":[{"obj":"Drum","say":"자기 번호 신호를 받으면 나타나 소리를 내요.","code":["ev^🚩 클릭했을 때","lk:숨기기","ev^{1} 신호를 받았을 때","lk:보이기","snd:{Low Tom} 끝까지 재생하기"]},{"obj":"Saxophone","say":"자기 번호 신호를 받으면 나타나 소리를 내요.","code":["ev^🚩 클릭했을 때","lk:숨기기","ev^{2} 신호를 받았을 때","lk:보이기","snd:{C2 Sax} 끝까지 재생하기"]},{"obj":"Guitar","say":"자기 번호 신호를 받으면 나타나 소리를 내요.","code":["ev^🚩 클릭했을 때","lk:숨기기","ev^{3} 신호를 받았을 때","lk:보이기","snd:{C2 guitar} 끝까지 재생하기"]},{"obj":"Trumpet","say":"자기 번호 신호를 받으면 나타나 소리를 내요.","code":["ev^🚩 클릭했을 때","lk:숨기기","ev^{4} 신호를 받았을 때","lk:보이기","snd:{C2 Trumpet} 끝까지 재생하기"]},{"obj":"Speaker","say":"악기 이름을 리스트에 넣고 번호를 물어요. 대답에 맞는 번호 신호를 보내요.","code":["ev^🚩 클릭했을 때","li:{악기자판기} 의 항목을 모두 삭제하기","li:⟦sen|{Drum} 의 {모양 이름}⟧ 을(를) {악기자판기} 에 추가하기","li:⟦sen|{Saxophone} 의 {모양 이름}⟧ 을(를) {악기자판기} 에 추가하기","li:⟦sen|{Guitar} 의 {모양 이름}⟧ 을(를) {악기자판기} 에 추가하기","li:⟦sen|{Trumpet} 의 {모양 이름}⟧ 을(를) {악기자판기} 에 추가하기","ev^🚩 클릭했을 때","sen:[몇 번 악기가 필요한가요?] 라고 묻고 기다리기",["ctl:만약 ⟪op|⟦sen|대답⟧ = [1]⟫ (이)라면",["ev:{1} 신호 보내기"]],["ctl:만약 ⟪op|⟦sen|대답⟧ = [2]⟫ (이)라면",["ev:{2} 신호 보내기"]],["ctl:만약 ⟪op|⟦sen|대답⟧ = [3]⟫ (이)라면",["ev:{3} 신호 보내기"]],["ctl:만약 ⟪op|⟦sen|대답⟧ = [4]⟫ (이)라면",["ev:{4} 신호 보내기"]]]}]}]},
